// 2026-02-14 Generated by IBM Bob
// Synchronize container images from qe-ceph-manifest repository to local registry
// Preserves full path structure and routes based on source registry

def call(Map parameters) {
    // Get parameters
    def manifestBranch = parameters.get("manifestBranch", "main")
    def releaseVersion = parameters.get("releaseVersion", "")
    def vendor = parameters.get("vendor", "")
    def dryRun = parameters.get("dryRun", false)

    // Validate vendor parameter
    if (!vendor || vendor.trim().isEmpty()) {
        echo "No vendor specified. Skipping image sync."
        return
    }

    echo "=== Container Image Sync from qe-ceph-manifest ==="
    echo "Manifest Branch: ${manifestBranch}"
    echo "Release Version: ${releaseVersion ?: 'All available releases'}"
    echo "Vendor: ${vendor}"
    echo "Dry Run: ${dryRun}"
    echo "=================================================="

    // Define manifest repository
    def manifestRepo = "https://github.com/ibmstorage/qe-ceph-manifest.git"
    def manifestDir = "manifest-${env.BUILD_NUMBER}"

    // Clone manifest repository
    echo "Cloning qe-ceph-manifest repository..."
    checkout([
        $class: "GitSCM",
        branches: [[name: manifestBranch]],
        userRemoteConfigs: [[url: manifestRepo]],
        extensions: [
            [
                $class: "RelativeTargetDirectory",
                relativeTargetDir: manifestDir
            ],
            [
                $class: "CloneOption",
                depth: 1,
                noTags: true,
                shallow: true,
                timeout: 10
            ]
        ]
    ])

    // Parse vendor list (comma-separated)
    def vendorList = vendor.split(',').collect { it.trim() }.findAll { it }

    // Filter out 'ceph' vendor as per requirements
    vendorList = vendorList.findAll { it != "ceph" }

    if (vendorList.isEmpty()) {
        echo "No valid vendors to process (ceph is ignored). Skipping sync."
        sh "rm -rf ${manifestDir}"
        return
    }

    echo "Processing vendors: ${vendorList.join(', ')}"

    // Determine release versions to process
    def releaseVersions = []
    if (releaseVersion && releaseVersion.trim()) {
        releaseVersions = [releaseVersion.trim()]
    } else {
        // Get all available release versions from manifest
        echo "No specific release version provided. Discovering available releases..."
        vendorList.each { vendorName ->
            def vendorDir = "${manifestDir}/${vendorName}"
            if (fileExists(vendorDir)) {
                def yamlFiles = sh(
                    script: "ls ${vendorDir}/*.yaml 2>/dev/null | xargs -n1 basename | sed 's/.yaml//' || true",
                    returnStdout: true
                ).trim()
                if (yamlFiles) {
                    yamlFiles.split('\n').each { version ->
                        if (version && !releaseVersions.contains(version)) {
                            releaseVersions << version
                        }
                    }
                }
            }
        }
    }

    if (releaseVersions.isEmpty()) {
        echo "No release versions found to process."
        sh "rm -rf ${manifestDir}"
        return
    }

    echo "Release versions to process: ${releaseVersions.join(', ')}"

    // Collect all images to sync
    def allImages = []

    // Parse images from each vendor and release
    releaseVersions.each { release ->
        echo "\n=== Processing Release: ${release} ==="

        vendorList.each { vendorName ->
            echo "\nProcessing ${vendorName} images for release ${release}..."

            def parsedImages = parseManifestImages(
                manifestDir: manifestDir,
                vendor: vendorName,
                releaseVersion: release
            )

            // Iterate through all root-level keys (e.g., z0, rc, nightly, released)
            parsedImages.each { section, imageList ->
                if (imageList && imageList.size() > 0) {
                    imageList.each { image ->
                        allImages << [
                            image: image,
                            vendor: vendorName,
                            section: section,
                            release: release
                        ]
                    }
                }
            }
        }
    }

    // Check if any images found
    if (allImages.isEmpty()) {
        echo "No images found in manifest for release ${releaseVersion}"
        return
    }

    echo "\nTotal images to sync: ${allImages.size()}"

    // Route images and prepare for sync
    def imagesToSync = []
    def skippedImages = []

    allImages.each { imageInfo ->
        def imageUrl = imageInfo.image
        def vendorName = imageInfo.vendor

        // Parse image URL
        def imageParts = imageUrl.tokenize('/')
        if (imageParts.size() < 2) {
            echo "Warning: Invalid image format: ${imageUrl}"
            skippedImages << imageUrl
            return
        }

        def sourceRegistry = imageParts[0]

        // Determine target repository based on source registry and vendor
        def targetRepo = determineTargetRepo(sourceRegistry, vendorName)

        if (targetRepo) {
            imagesToSync << imageUrl
            echo "  [${vendorName}] ${imageUrl} -> ${targetRepo}"
        } else {
            echo "  [SKIP] Unknown registry for: ${imageUrl}"
            skippedImages << imageUrl
        }
    }

    // Summary before sync
    echo "\n=== Sync Summary ==="
    echo "Images to sync: ${imagesToSync.size()}"
    echo "Skipped images: ${skippedImages.size()}"
    echo "===================="

    // Perform sync if not dry run
    if (dryRun) {
        echo "\n[DRY RUN] Skipping actual image sync"
        echo "The following images would be synced:"
        imagesToSync.each { image ->
            echo "  - ${image}"
        }
    } else {
        if (imagesToSync.isEmpty()) {
            echo "No images to sync"
            return
        }

        echo "\nStarting image synchronization..."

        // Convert list to multiline string for syncBlueImages
        def imagesString = imagesToSync.join("\n")

        try {
            // Use existing syncBlueImages function
            syncBlueImages(images: imagesString)
            echo "\n✓ Successfully synced ${imagesToSync.size()} images"
        } catch (Exception e) {
            echo "\n✗ Error during image sync: ${e.getMessage()}"
            throw e
        }
    }

    // Cleanup manifest directory
    echo "\nCleaning up manifest directory..."
    sh "rm -rf ${manifestDir}"

    echo "\n=== Sync Complete ==="
}

// Helper function to determine target repository based on source registry
def determineTargetRepo(String sourceRegistry, String vendor) {
    if (vendor == "ibm") {
        // IBM routing logic
        if (sourceRegistry == "cp.icr.io") {
            return "ibm-prod/"
        } else if (sourceRegistry == "cp.stg.icr.io") {
            return "ibm-stage/"
        } else if (sourceRegistry == "preprod.icr.io") {
            return "ibm-stage/"
        } else {
            throw new RuntimeException("Unsupported IBM registry: ${sourceRegistry}")
        }
    } else if (vendor == "redhat") {
        // RedHat routing logic
        if (sourceRegistry == "registry.redhat.io") {
            return "rh-prod/"
        } else if (sourceRegistry == "registry.stage.redhat.io") {
            return "rh-stage/"
        } else if (sourceRegistry == "quay.io") {
            return "rh-stage/"
        } else if (sourceRegistry == "brew.registry.redhat.io") {
            return "rh-stage/"
        } else {
            return "rh-stage/"
        }
    }

    return null
}
